// Pure Mantra Self-Contained Embedded Asset Fallbacks (Ensures 100% display reliability even without folders)
window.PURE_MANTRA_ASSETS = {
  logo: 'data:image/jpeg;base64,',
  fssai: 'data:image/png;base64,',
  products: {
    'bringa-brahmi': 'data:image/jpeg;base64,',
    'chyavanaprashyam': 'data:image/jpeg;base64,',
    'danwantaram-tailam': 'data:image/jpeg;base64,',
    'hibiscus-leaf-powder': 'data:image/jpeg;base64,',
    'krishnaveni-hair-oil': 'data:image/jpeg;base64,',
    'kumkumadi-tailam': 'data:image/jpeg;base64,',
    'lavanyam-banner': 'data:image/jpeg;base64,',
    'lavanyam-tailam': 'data:image/jpeg;base64,',
    'manjishta-lip-balm': 'data:image/jpeg;base64,',
    'matru-devo-bhava': 'data:image/jpeg;base64,',
    'neelibringadi-oil': 'data:image/jpeg;base64,',
    'rasnadi-churnam': 'data:image/jpeg;base64,',
    'surabhi-soundarya': 'data:image/jpeg;base64,',
    'tejaswini-mugha-lepam': 'data:image/jpeg;base64,',
    'triphala-shampoo': 'data:image/jpeg;base64,',
    'virgin-coconut-oil': 'data:image/jpeg;base64,'
  }
};

// Robust alias mapping and resolver function
if (typeof window !== 'undefined' && window.PURE_MANTRA_ASSETS && window.PURE_MANTRA_ASSETS.products) {
  var p = window.PURE_MANTRA_ASSETS.products;
  if (p['bringa-brahmi'] && !p['bringa-brahmi-oil']) p['bringa-brahmi-oil'] = p['bringa-brahmi'];
  if (p['surabhi-soundarya'] && !p['surabhi-soundarya-snan']) p['surabhi-soundarya-snan'] = p['surabhi-soundarya'];
}

if (typeof window !== 'undefined') {
  window.resolveProductImg = function(id, defaultPath) {
    if (window.PURE_MANTRA_ASSETS && window.PURE_MANTRA_ASSETS.products) {
      var p = window.PURE_MANTRA_ASSETS.products;
      var filename = defaultPath ? defaultPath.split('/').pop().replace(/\.[^.]+$/, '') : '';
      return p[id] || p[filename] || p[id.replace(/-oil$/, '')] || p[id.replace(/-snan$/, '')] || defaultPath;
    }
    return defaultPath;
  };
}